<?phpnamespace app\api\model;use think\facade\Cache;use hema\Helper;/** * 购物车管理 */class Cart{    public $error = '';	//错误信息    private $user_id;	//用户id    private $cart_cache;    //购物车缓存    private $cart = [];	//购物车列表    private $clear = false;	//是否清空购物车    /**     * 构造方法     */    public function __construct($user_id)    {        $this->user_id = $user_id;        $this->cart_cache = 'cart_' . $this->user_id;        $this->cart = Cache::get($this->cart_cache) ?: [];    }        /**     * 析构方法     * 将cart数据保存到缓存文件     */    public function __destruct()    {        $this->clear !== true && Cache::set($this->cart_cache, $this->cart, 86400);    }         /**     * 清空当前用户购物车     */    public function clearAll()    {        $this->clear = true;        Cache::delete($this->cart_cache);    }	 /**     * 获取购物车内容     */    public function getCart()    {		return $this->cart;	}    public function getList($order_mode)    {        // 商品列表        $goodsList = [];        $goodsIds = array_unique(array_column($this->cart, 'goods_id'));        foreach ((new Goods)->getListByIds($goodsIds) as $goods) {            $goodsList[$goods['goods_id']] = $goods;        }        $is_stock = Setting::getItem('goods')['is_stock'];//获取是否开启库存配置        $pack_price = 0;//餐盒费        $min_price = 0;//起送价价        // 购物车商品列表        $cartList = [];        foreach ($this->cart as $key => $cart) {            // 判断商品不存在则自动删除            if (!isset($goodsList[$cart['goods_id']])) {                $this->delete($cart);                continue;            }            //自动删除库存不足得商品            if($is_stock == 1){                if($goodsList[$cart['goods_id']]['stock'] == 0){                    $this->delete($cart);                    continue;                }else{                    if($goodsList[$cart['goods_id']]['stock'] < $cart['goods_num']){                        $cart['goods_num'] = $goodsList[$cart['goods_id']]['stock'];                        $this->edit($cart);                    }                }            }                        $goods = clone $goodsList[$cart['goods_id']];            // 商品sku信息            $goods['goods_sku_id'] = $cart['goods_sku_id'];            // 商品sku不存在则自动删除            if (!$goods['goods_sku'] = $goods->getGoodsSku($cart['goods_sku_id'])) {                $this->delete($cart);                continue;            }            // 判断商品是否下架            if ($goods['goods_status']['value'] != 10) {                $this->setError('很抱歉，商品 [' . $goods['goods_name'] . '] 已下架');            }                        //如果是外卖,计算餐盒费			if($order_mode == 20 or $order_mode == 30){				if($goods['pack_price']>0){					$pack_price = $pack_price + $goods['pack_price']*$cart['goods_num'];				}			}			// 商品单价			$goods['goods_price'] = $goods['goods_sku']['goods_price'];			// 商品总价			$goods['total_num'] = $cart['goods_num'];			$goods['total_price'] = $total_price = bcmul($goods['goods_price'], $cart['goods_num'], 2);            $cartList[] = $goods->hidden(['category','spec']);        }        // 商品总金额        $orderTotalPrice = Helper::getArrayColumnSum($cartList, 'total_price');        //餐盒费加入总价	    $order_pay_price = $orderTotalPrice + $pack_price;		//如果是外卖		if($order_mode == 20){			$delivery = Setting::getItem('delivery');			if($delivery['min_price'] > $order_pay_price){			    $min_price = $delivery['min_price'] - $order_pay_price;// 起送价价			}		}        return [            'coupon_list' => null, //优惠券列表            'gift' => null,//赠品            'goods_list' => $cartList,                       // 商品列表            'order_total_num' => $this->getTotalNum(),       // 商品总数量            'order_total_price' => Helper::number2($orderTotalPrice),// 商品总金额            'order_pay_price' => Helper::number2($order_pay_price),    // 实际支付金额+餐盒费			'pack_price' => Helper::number2($pack_price),	// 餐盒费用			'min_price' => Helper::number2($min_price),//最低启送价			'delivery_price' => Helper::number2(0),//配送费用			'activity_price' => Helper::number2(0),//优惠费用			'vip_price' => Helper::number2(0),//优惠费用			'address' => null,//收货地址			'intra_region' => false,//是否超出配送范围			'free_delivery' => false,//免配送费            'has_error' => $this->hasError(),            'error_msg' => $this->getError(),        ];    }        /**     * 购物车操作     */    public function edit($data)    {        //商品数量为空，什么也不做        if($data['goods_num'] == ''){            return true;        }        //商品数量0为删除        if($data['goods_num'] == 0){            return $this->delete($data);        }                // 购物车商品索引        $index = $data['goods_id'] . '_' . $data['goods_sku_id'];        $data['create_time'] = time();        //判断起售数量        // 商品信息        $goods = Goods::detail($data['goods_id']);        // 判断商品是否下架        if ($goods['goods_status']['value'] != 10) {            $this->setError('很抱歉，该商品已下架');            return false;        }        if($data['goods_num'] < (int)$goods['start_sale']){            $data['goods_num'] = (int)$goods['start_sale'];        }        $this->cart[$index] = $data;        return true;    }    /**     * 添加购物车     */    public function add($data)    {        // 购物车商品索引        $index = $data['goods_id'] . '_' . $data['goods_sku_id'];        $data['create_time'] = time();        // 商品信息        $goods = Goods::detail($data['goods_id']);        // 判断商品是否下架        if ($goods['goods_status']['value'] != 10) {            $this->setError('很抱歉，该商品已下架');            return false;        }        if(isset($this->cart[$index])){            $this->cart[$index]['goods_num'] = $this->cart[$index]['goods_num'] + $data['goods_num'];            //判断起售数量            if($this->cart[$index]['goods_num'] < (int)$goods['start_sale']){                $this->cart[$index]['goods_num'] = (int)$goods['start_sale'];            }        }else{            //判断起售数量            if($data['goods_num'] < (int)$goods['start_sale']){                $data['goods_num'] = (int)$goods['start_sale'];            }            $this->cart[$index] = $data;        }        return true;    }    /**     * 减少购物车中某商品数量     */    public function sub($data)    {        $index = $data['goods_id'] . '_' . $data['goods_sku_id'];        $goods_num = $this->cart[$index]['goods_num'] - 1;// 商品信息        //判断是否低于起售数量        $goods = Goods::detail($data['goods_id']);        if($goods_num >= 1 and $goods_num >= $goods['start_sale']){            $this->cart[$index]['goods_num'] = $goods_num;        }else{            unset($this->cart[$index]); //清空该商品            return true;        }        $this->cart[$index]['goods_num'] = $goods_num;        return true;    }    /**     * 删除购物车中指定商品     */    public function delete($data)    {        //为空是商城批量删除        if(empty($data['goods_id'])){            $indexArr = strpos( $data['goods_sku_id'], ',') !== false ? explode(',',  $data['goods_sku_id']) : [ $data['goods_sku_id']];            foreach ($indexArr as $index) {                if (isset($this->cart[$index])) unset($this->cart[$index]);            }        }else{            $index = $data['goods_id'] . '_' . $data['goods_sku_id'];            if (isset($this->cart[$index])) unset($this->cart[$index]);        }        return true;    }    /**     * 获取当前商品在购物车的数量     */    public function getGoodsNum($goods)    {        $total_num = 0;//购物车商品总量        foreach ($goods['spec'] as $index=>$vo){            $goods_sku = $goods['goods_id'] . '_' . $vo['spec_sku_id'];            $goods['spec'][$index]['sell_num'] = 0;//初始规格内销量为0            //判断是否在购物车内            if(isset($this->cart[$goods_sku]['goods_num'])){                $goods['spec'][$index]['sell_num'] = $this->cart[$goods_sku]['goods_num'];                $total_num += $this->cart[$goods_sku]['goods_num'];//总量累加            }        }        $goods['total_num'] = $total_num;        return $goods;    }    /**     * 获取当前用户购物车商品总数量     */    public function getTotalNum()    {        return array_sum(array_column($this->cart, 'goods_num'));    }    /**     * 设置错误信息     */    private function setError($error)    {        empty($this->error) && $this->error = $error;    }    /**     * 是否存在错误     */    private function hasError()    {        return !empty($this->error);    }    /**     * 获取错误信息     */    public function getError()    {        return $this->error;    }}